<?php require_once "../db.php";require_role("Teacher");$uid=current_id();if($_SERVER["REQUEST_METHOD"]==="POST"){$title=trim($_POST["title"]);$subject=trim($_POST["subject"]);$desc=trim($_POST["description"]);$content=trim($_POST["content"]);$s=$conn->prepare("INSERT INTO practice_material(title,description,subject,content,created_by) VALUES(?,?,?,?,?)");$s->bind_param("ssssi",$title,$desc,$subject,$content,$uid);$s->execute();} $r=$conn->query("SELECT * FROM practice_material ORDER BY id DESC");?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Practice Material</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container-fluid"><div class="row"><div class="col-lg-2 p-0"><?php include "../partials/teacher_sidebar.php";?></div><main class="col-lg-10"><div class="py-4"><h2 class="fw-bold">Practice Material</h2><div class="card panel-card mb-4"><div class="card-body"><form method="post"><div class="row g-2"><div class="col-md-6"><input name="title" class="form-control" placeholder="Title" required></div><div class="col-md-6"><input name="subject" class="form-control" placeholder="Subject"></div><div class="col-12"><input name="description" class="form-control" placeholder="Description"></div><div class="col-12"><textarea name="content" class="form-control" rows="4" placeholder="Content" required></textarea></div><div><button class="btn btn-primary">Add Material</button></div></div></form></div></div><div class="row g-3"><?php while($m=$r->fetch_assoc()):?><div class="col-md-6"><div class="card panel-card p-3"><b><?=e($m["title"])?></b><small class="text-muted"><?=e($m["subject"])?></small><p><?=e($m["description"])?></p></div></div><?php endwhile;?></div></div></main></div></div></body></html>
